"""The grade 8 maths course ("מתמטיקה כיתה ח"): the Israeli Ministry of Education
programme for כיתה ח, geometry first. Angles and parallel lines, congruent and
isosceles triangles, a long Pythagoras unit, the coordinate plane, quadrilaterals,
areas, solids, then algebra (powers, roots, technique, equations), linear
functions and systems, statistics and probability.

Figures are drawn by js/exercises/geo.js from the 'fig' language (points on
maths axes, y up). Interactive types: pyth (squares on the sides), plot (tap a
point on a grid), angles (tap an angle on crossing / parallel lines), blitz (a
timed quick-fire game). Built by think_content.py.
"""
from think_content import T, MC, N, ORD, SORT, _extra
from think_deep import U

ID = 'math8'


def FIG(pts, **kw):
    return {'pts': pts, **kw}


def TF(title_he, fig, *body):
    """An idea card with a figure instead of the course icon."""
    return {**T(title_he, *body), 'fig': fig}


def PY(prompt, answer, explain, hint=None, **kw):
    return _extra({'type': 'pyth', 'prompt_he': prompt, 'answer': str(answer)}, explain, hint, kw)


def PYX(prompt, **kw):
    return {'type': 'pyth', 'prompt_he': prompt, 'explore': True, **kw}


def PLOT(prompt, answer, explain, hint=None, **kw):
    return _extra({'type': 'plot', 'prompt_he': prompt, 'answer': answer}, explain, hint, kw)


def PLOTX(prompt, **kw):
    return {'type': 'plot', 'prompt_he': prompt, 'explore': True, **kw}


def ANGS(prompt, answer, explain, hint=None, **kw):
    return _extra({'type': 'angles', 'prompt_he': prompt, 'answer': answer}, explain, hint, kw)


def ANGSX(prompt, **kw):
    return {'type': 'angles', 'prompt_he': prompt, 'explore': True, **kw}


def BLITZ(prompt, pool, seconds=45):
    return {'type': 'blitz', 'prompt_he': prompt, 'pool': pool, 'seconds': seconds}


# Reusable figures.
RT = FIG({'A': [0, 0], 'B': [4, 0], 'C': [0, 3]}, segs=[['A', 'B'], ['B', 'C'], ['C', 'A']], angles=[{'at': 'A', 'from': 'B', 'to': 'C', 'right': True}], names=True)


def rt_fig(a, b, la=None, lb=None, lc=None, right_label=None, extra_angles=()):
    """A right triangle with legs a (along x) and b (along y) and side labels."""
    segs = [['A', 'B', {'label': la, 'side': -1} if la else {}], ['A', 'C', {'label': lb, 'side': 1} if lb else {}], ['B', 'C', {'label': lc, 'side': 1, 'color': 2} if lc else {}]]
    return FIG({'A': [0, 0], 'B': [a, 0], 'C': [0, b]}, segs=segs, angles=[{'at': 'A', 'from': 'B', 'to': 'C', 'right': True}, *extra_angles])


def iso_fig(base=6, h=4.5, with_median=False, labels=None, angles=()):
    pts = {'A': [0, 0], 'B': [base, 0], 'C': [base / 2, h]}
    segs = [['A', 'B', {}], ['B', 'C', {'ticks': 1}], ['C', 'A', {'ticks': 1}]]
    angs = list(angles)
    if with_median:
        pts['D'] = [base / 2, 0]
        segs.append(['C', 'D', {'dash': True, 'color': 1}])
        segs[0] = ['A', 'B', {}]
        angs.append({'at': 'D', 'from': 'B', 'to': 'C', 'right': True, 'color': 1})
    for lab in labels or []:
        segs.append(lab)
    return FIG(pts, segs=segs, angles=angs, names=True)


