def small_tri(kind):
    """Figures for the "which quadrilateral" picks."""
    if kind == 'rhombus':
        return FIG({'A': [0, 0], 'B': [2, 1.2], 'C': [0, 2.4], 'D': [-2, 1.2]}, poly=[{'of': ['A', 'B', 'C', 'D'], 'color': 1}])
    if kind == 'rect':
        return FIG({'A': [0, 0], 'B': [3, 0], 'C': [3, 1.8], 'D': [0, 1.8]}, poly=[{'of': ['A', 'B', 'C', 'D'], 'color': 0}])
    if kind == 'square':
        return FIG({'A': [0, 0], 'B': [2.2, 0], 'C': [2.2, 2.2], 'D': [0, 2.2]}, poly=[{'of': ['A', 'B', 'C', 'D'], 'color': 2}])
    if kind == 'trap':
        return FIG({'A': [0, 0], 'B': [3.4, 0], 'C': [2.5, 1.8], 'D': [0.9, 1.8]}, poly=[{'of': ['A', 'B', 'C', 'D'], 'color': 3}])
    raise ValueError(kind)


def line_fig(m, b, rng=3):
    """A small grid with the line y = mx + b."""
    return FIG({'_P': [-rng, m * -rng + b], '_Q': [rng, m * rng + b]}, grid=rng, lines=[['_P', '_Q']])


